<template>
    <div>
        <h1>Note Hierarchy v1</h1>

        <v-row class="mb-4">
            <v-col cols="12">
                <v-btn @click="openCreateDialog" color="success" class="mr-2">Add New Page</v-btn>
                <v-btn @click="toggleDeleteButtons" :color="showDeleteButtons ? 'error' : 'primary'">
                    {{ showDeleteButtons ? 'Hide Delete Buttons' : 'Show Delete Buttons' }}
                </v-btn>
            </v-col>
        </v-row>

        <v-dialog v-model="dialog" max-width="400">
            <v-card>
                <v-card-title>Create New</v-card-title>
                <v-card-text>
                    <v-text-field
                        v-model="newNoteName"
                        label="Name"
                        :error-messages="nameError"
                        @input="validateName"
                    ></v-text-field>
                    <p>Do you want to create an item or a folder?</p>
                </v-card-text>
                <v-card-actions>
                    <v-btn color="primary" @click="createNewPage('p')" :disabled="!newNoteName">Item</v-btn>
                    <v-btn color="primary" @click="createNewPage('h')" :disabled="!newNoteName">Folder</v-btn>
                    <v-btn color="secondary" @click="closeDialog">Cancel</v-btn>
                </v-card-actions>
            </v-card>
        </v-dialog>

        <v-snackbar v-model="showSuccessMessage" color="success" timeout="3000">
            New page added successfully!
            <template v-slot:actions>
                <v-btn variant="text" @click="showSuccessMessage = false">Close</v-btn>
            </template>
        </v-snackbar>

        <v-snackbar v-model="showDeleteSuccessMessage" color="success" timeout="3000">
            Note deleted successfully!
            <template v-slot:actions>
                <v-btn variant="text" @click="showDeleteSuccessMessage = false">Close</v-btn>
            </template>
        </v-snackbar>

        <v-progress-circular v-if="loading" indeterminate color="primary"></v-progress-circular>
        <div v-if="error" class="error-message">{{ error.message }}</div>

        <table v-if="!loading && !error">
            <tbody>
                <NoteItem
                    v-for="note in topLevelNotes"
                    :key="note.id"
                    :note="note"
                    :level="0"
                    :parentName="note.attributes.name"
                    :activeNoteId="activeNoteId"
                    :on-save="saveContact"
                    :showDeleteButtons="showDeleteButtons"
                    @updateActiveNote="setActiveNote"
                    @deleteNote="deleteNote"
                />
            </tbody>
        </table>
        <div v-if="topLevelNotes.length === 0 && !loading" class="empty-state">
            No notes found. Click "Add New Page" to create your first note.
        </div>
    </div>
</template>

<script>
import { gql } from '@apollo/client';
import { ref, computed } from 'vue';
import client from '../apollo-client';
import NoteItem from './NoteItem.vue';

const GET_ALL_NOTE_TAKES = gql`
  query GetAllNoteTakes {
    noteTakes(
      sort: "name", 
      filters: { parentIds: { id: { eq: null } } }, 
      pagination: { limit: 1000 }
    ) {
      data {
        id
        attributes {
          name
          type
          description
          hide
          emoji
          block
          parentIds {
            data {
              id
              attributes {
                name
              }
            }
          }
          child_ids(
            pagination: { limit: 1000 }
          ) {
            data {
              id
              attributes {
                name
                type
                description
                hide
                emoji
                block
                parentIds {
                  data {
                    id
                    attributes {
                      name
                    }
                  }
                }
                child_ids(
                  pagination: { limit: 1000 }
                ) {
                  data {
                    id
                    attributes {
                      name
                      type
                      description
                      hide
                      emoji
                      block
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
`;

const CREATE_NOTE_MUTATION = gql`
  mutation CreateNoteTake($name: String!, $type: String!, $parentIds: [ID]) {
    createNoteTake(data: { 
      name: $name, 
      type: $type, 
      block: { blocks: [] },
      hide: false,
      parentIds: $parentIds
    }) {
      data {
        id
        attributes {
          name
          type
          block
          parentIds {
            data {
              id
            }
          }
        }
      }
    }
  }
`;

const UPDATE_NOTE_MUTATION = gql`
  mutation UpdateNoteBlock($id: ID!, $block: JSON!) {
    updateNoteTake(id: $id, data: { block: $block }) {
      data {
        id
        attributes {
          block
        }
      }
    }
  }
`;

const DELETE_NOTE_MUTATION = gql`
  mutation DeleteNoteTake($id: ID!) {
    deleteNoteTake(id: $id) {
      data {
        id
      }
    }
  }
`;

export default {
    components: {
        NoteItem
    },
    setup() {
        const notes = ref([]);
        const loading = ref(true);
        const error = ref(null);
        const activeNoteId = ref(null);
        const dialog = ref(false);
        const newNoteName = ref('');
        const nameError = ref('');
        const showSuccessMessage = ref(false);
        const showDeleteSuccessMessage = ref(false);
        const showDeleteButtons = ref(false);

        const toggleDeleteButtons = () => {
            showDeleteButtons.value = !showDeleteButtons.value;
            console.log('Toggled showDeleteButtons:', showDeleteButtons.value);
        };

        const setActiveNote = (noteId) => {
            activeNoteId.value = noteId;
        };

        const openCreateDialog = () => {
            newNoteName.value = '';
            nameError.value = '';
            dialog.value = true;
        };

        const closeDialog = () => {
            dialog.value = false;
            newNoteName.value = '';
            nameError.value = '';
        };

        const validateName = () => {
            nameError.value = newNoteName.value.trim() ? '' : 'Name is required';
        };

        const createNewPage = async (type) => {
            if (!newNoteName.value.trim()) {
                nameError.value = 'Name is required';
                return;
            }

            try {
                const parentIds = activeNoteId.value ? [activeNoteId.value] : null;
                await client.mutate({
                    mutation: CREATE_NOTE_MUTATION,
                    variables: {
                        name: newNoteName.value.trim(),
                        type,
                        parentIds
                    },
                    refetchQueries: [{ query: GET_ALL_NOTE_TAKES }],
                });
                closeDialog();
                showSuccessMessage.value = true;
                await fetchNotes();
            } catch (error) {
                console.error('Error creating new page:', error);
                nameError.value = 'Failed to create note. Try again.';
            }
        };

        async function saveContact(noteId, updatedBlockContent) {
            try {
                const findNoteIndex = (notesArray, id) => {
                    for (let i = 0; i < notesArray.length; i++) {
                        if (notesArray[i].id === id) return i;
                        if (notesArray[i].attributes.child_ids?.data) {
                            const childIndex = findNoteIndex(notesArray[i].attributes.child_ids.data, id);
                            if (childIndex !== -1) return childIndex;
                        }
                    }
                    return -1;
                };
                
                const noteIndex = findNoteIndex(notes.value, noteId);
                if (noteIndex === -1) return;

                await client.mutate({
                    mutation: UPDATE_NOTE_MUTATION,
                    variables: {
                        id: noteId,
                        block: updatedBlockContent,
                    },
                });
                console.log('Note updated successfully!');
            } catch (err) {
                console.error('Error updating note:', err);
            }
        }

        const deleteNote = async (noteId) => {
            try {
                await client.mutate({
                    mutation: DELETE_NOTE_MUTATION,
                    variables: { id: noteId },
                    refetchQueries: [{ query: GET_ALL_NOTE_TAKES }],
                });
                showDeleteSuccessMessage.value = true;
                await fetchNotes();
                if (activeNoteId.value === noteId) {
                    activeNoteId.value = null;
                }
            } catch (err) {
                console.error('Error deleting note:', err);
                error.value = { message: 'Failed to delete note. Try again.' };
            }
        };

        const fetchNotes = async () => {
            try {
                const response = await client.query({
                    query: GET_ALL_NOTE_TAKES,
                    fetchPolicy: 'network-only'
                });
                notes.value = response.data.noteTakes.data;
            } catch (err) {
                error.value = err;
                console.error('Error loading notes:', err);
            } finally {
                loading.value = false;
            }
        };

        const topLevelNotes = computed(() => {
            return notes.value.filter(note => 
                !note.attributes.parentIds.data || 
                note.attributes.parentIds.data.length === 0
            );
        });

        fetchNotes();

        return {
            notes,
            loading,
            error,
            topLevelNotes,
            activeNoteId,
            setActiveNote,
            saveContact,
            createNewPage,
            dialog,
            openCreateDialog,
            closeDialog,
            newNoteName,
            nameError,
            validateName,
            showSuccessMessage,
            showDeleteSuccessMessage,
            deleteNote,
            showDeleteButtons,
            toggleDeleteButtons
        };
    },
};
</script>

<style scoped>
table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    border: 1px solid #ddd;
    padding: 6px;
}

th {
    background-color: #f2f2f2;
}
</style>