<template>
  <v-container style="background-color: aliceblue">
    <hr>
    <v-card class="mx-auto" max-width="100%">
      <hr>
      <v-card-text>
        <div ref="editorjs" style="min-height: 100px;"></div>
      </v-card-text>
    </v-card>
  </v-container>

  <v-row class="mt-4">
    <v-col cols="12">
      <v-btn @click="saveContent" color="primary">Test Content</v-btn>
    </v-col>
  </v-row>

  <v-row class="mt-4">
    <v-col cols="12">
      <v-card>
        <v-card-title>Saved Output</v-card-title>
        <v-card-text>
          <pre>{{ savedData }}</pre>
        </v-card-text>
      </v-card>
    </v-col>
  </v-row>
</template>

<script>
import EditorJS from '@editorjs/editorjs';
import Header from '@editorjs/header';
import List from '@editorjs/list';
import Quote from '@editorjs/quote';
import Table from '@editorjs/table';
import Checklist from '@editorjs/checklist';
import Embed from '@editorjs/embed';
import Delimiter from '@editorjs/delimiter';
import SimpleImage from '@editorjs/simple-image';
import dbTableTool from './dbTableTool';
import editorjsNestedChecklist from '@calumk/editorjs-nested-checklist';
import Paragraph from '@editorjs/paragraph';
import CloudinaryVideoTool from './CloudinaryVideoTool';
import marker from './MarkerTool';
import HelloWorldTool from './ToolInsetOptionWords';
import SelectWords from './ToolSelectWords';
import CodeBlockTool from './CodeBlockTool';
import TextBlockTool from './TextBlockTool';
import 'prismjs';
import 'prismjs/themes/prism.css';
import 'quill/dist/quill.snow.css';

export default {
  name: "EnhancedEditor",
  props: {
    initialData: {
      type: Object,
      required: true
    }
  },
  data() {
    return {
      editor: null,
      savedData: null,
    };
  },
  mounted() {
    this.$nextTick(() => {
      this.initEditor();
    });
  },
  beforeUnmount() {
    if (this.editor) {
      this.editor.destroy();
      this.editor = null;
    }
  },
  methods: {
    async initEditor() {
      const editorElement = this.$refs.editorjs;
      if (!editorElement) {
        console.error('EditorJS ref not found');
        return;
      }

      // Validate initialData
      const data = {
        time: this.initialData.time || Date.now(),
        blocks: Array.isArray(this.initialData.blocks) ? this.initialData.blocks : [],
        version: this.initialData.version || '2.30.6'
      };
      console.log('EditorJS initial data:', data);

      try {
        this.editor = new EditorJS({
          holder: editorElement,
          data: data,
          tools: {
            nestedchecklist: editorjsNestedChecklist,
            paragraph: {
              class: Paragraph,
              inlineToolbar: true,
              config: {
                placeholder: 'Type here...',
                inlineToolbar: ['link', 'bold', 'italic']
              },
            },
            header: {
              class: Header,
              inlineToolbar: ['link', 'bold', 'italic'],
              config: {
                placeholder: 'Enter a heading',
              },
            },
            list: {
              class: List,
              inlineToolbar: ['link', 'bold', 'italic'],
            },
            cloudinaryVideo: {
              class: CloudinaryVideoTool,
            },
            image: {
              class: SimpleImage,
            },
            quote: {
              class: Quote,
              inlineToolbar: ['link', 'bold', 'italic'],
              config: {
                quotePlaceholder: 'Enter a quote',
                captionPlaceholder: 'Quotes author',
              },
            },
            table: {
              class: Table,
              inlineToolbar: ['link', 'bold', 'italic'],
              config: {
                rows: 2,
                cols: 3,
              },
            },
            checklist: {
              class: Checklist,
              inlineToolbar: true,
            },
            embed: {
              class: Embed,
              inlineToolbar: true,
            },
            delimiter: Delimiter,
            dbTable: {
              class: dbTableTool,
              inlineToolbar: true,
            },
            vueTool: marker,
            InsertText: HelloWorldTool,
            SelectWords: SelectWords,
            codeBlock: {
              class: CodeBlockTool,
              inlineToolbar: true,
            },
            textBlock: {
              class: TextBlockTool,
              inlineToolbar: true,
            },
          },
          inlineToolbar: ['link', 'bold', 'italic'],
          toolbar: {
            inlineToolbar: true,
            tools: {
              vueTool: {
                title: 'Vue Tool',
                icon: '<span>VT</span>',
              },
              codeBlock: {
                title: 'Code Block',
                icon: '<span>CB</span>',
              },
              textBlock: {
                title: 'Text Block',
                icon: '<span>TB</span>',
              },
            },
          },
          onReady: () => {
            console.log('Editor.js is ready');
          },
          onError: (error) => {
            console.error('Editor.js error:', error);
          }
        });
      } catch (error) {
        console.error('Editor.js failed to initialize:', error);
      }
    },
    async saveContent() {
      try {
        const outputData = await this.editor.save();
        this.savedData = JSON.stringify(outputData, null, 2);
        console.log('Saved Data:', outputData);
      } catch (error) {
        console.error('Saving failed:', error);
      }
    },
    async getSavedData() {
      try {
        const outputData = await this.editor.save();
        return outputData;
      } catch (error) {
        console.error('Failed to get saved data:', error);
        return null;
      }
    }
  }
};
</script>

<style scoped>
/* Main container styles */
div.code-block-tool {
  margin: 8px 0;
  background: #f5f5f5;
  border: 1px solid #ddd;
  border-radius: 4px;
  padding: 10px;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  overflow: visible !important;
}

div.code-block-tool div.code-display-container,
div.code-block-tool div.editor-container {
  margin-bottom: 15px;
  border-bottom: 1px solid #eee;
  padding-bottom: 15px;
}

div.code-block-tool div.code-block-content.hidden {
  display: none !important;
}

div.code-block-tool.editable div.code-block-content.code-view-content pre {
  display: block !important;
}

div.code-block-tool.read-only div.code-block-content pre {
  display: block !important;
}

div.code-block-tool pre {
  margin: 0;
  background: none;
  border: none;
  padding: 0;
  overflow-x: auto;
}

div.code-block-tool code {
  display: block;
  font-family: 'Courier New', Courier, monospace;
  font-size: 14px;
  line-height: 1.5;
  white-space: pre-wrap;
  min-height: 50px;
  padding: 10px;
}

div.code-block-tool textarea.code-block-textarea {
  width: calc(100% - 20px) !important;
  min-width: 200px !important;
  min-height: 100px !important;
  font-family: 'Courier New', Courier, monospace !important;
  font-size: 14px !important;
  line-height: 1.5 !important;
  background: transparent !important;
  border: 1px solid #ccc !important;
  border-radius: 4px !important;
  padding: 10px !important;
  margin-bottom: 8px !important;
  resize: both !important;
  white-space: pre-wrap !important;
  box-sizing: border-box !important;
}

div.code-block-tool.read-only textarea.code-block-textarea {
  display: none !important;
}

div.code-block-tool textarea.code-block-textarea:focus {
  outline: none !important;
}

div.code-block-tool select.code-language-select {
  margin-top: 8px;
  padding: 4px;
  width: 150px;
}

div.code-block-tool button.code-block-toggle {
  display: block !important;
  padding: 5px 10px !important;
  background: #007bff !important;
  color: #fff !important;
  border: none !important;
  border-radius: 4px !important;
  cursor: pointer !important;
  margin-bottom: 8px !important;
  font-size: 14px !important;
  z-index: 1000 !important;
  position: relative !important;
}

div.code-block-tool button.code-view-toggle {
  background: #007bff !important;
}

div.code-block-tool button.editor-toggle {
  background: #28a745 !important;
}

div.code-block-tool button.code-block-toggle:hover {
  opacity: 0.9 !important;
}

.ce-block div.code-block-tool div.code-block-content.hidden {
  display: none !important;
}

.ce-block div.code-block-tool button.code-block-toggle {
  display: block !important;
}
</style>